struct TaggedPtr { Node* ptr; int tag; };
atomic<TaggedPtr> top;

void push(int v) {
  TaggedPtr old = top.load();
  Node* n = new Node{v, old.ptr};
  TaggedPtr new_val{ n, old.tag + 1 };
  while (!top.compare_exchange_weak(old, new_val));
}

int pop() {
  TaggedPtr old = top.load();
  while (old.ptr && !top.compare_exchange_weak(old, {old.ptr->next, old.tag + 1}));
  return old.ptr ? old.ptr->val : -1;
}
```

